macro_rules! rules {
    ($m:ident { $($id:ident = $s:literal),+ $(,)? }) => {
        mod $m {
            #[allow(non_camel_case_types, dead_code, clippy::upper_case_acronyms)]
            #[repr(u16)]
            enum Index {
                $($id),+
            }
            $(
                #[allow(dead_code)]
                pub const $id: u16 = Index::$id as u16;
            )+
            pub const NAMES: &[&str] = &[$($s),+];
        }
    };
}

