#[inline]
fn hit(rule: u16, category: u16, milli: u16) -> i64 {
    i64::from(category) | (i64::from(milli) << 16) | (i64::from(rule) << 32)
}

fn flag(flags: u32, bit: u32) -> bool {
    flags & bit != 0
}

#[inline]
fn is_sep(b: u8) -> bool {
    matches!(b, b'.' | b'-' | b'_' | b' ')
}

